<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_admin();$aid=(int)current_user()['user_id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf_token']??null);$id=(int)$_POST['user_id'];if($id===$aid){flash('error','You cannot disable the current administrator.');redirect('admin/users.php');}$action=$_POST['action']??'';if($action==='toggle')db()->prepare('UPDATE users SET status=IF(status="disabled","active","disabled") WHERE user_id=? AND role="student"')->execute([$id]);elseif($action==='reset'&&strlen($_POST['new_password']??'')>=8)db()->prepare('UPDATE users SET password_hash=? WHERE user_id=? AND role="student"')->execute([password_hash($_POST['new_password'],PASSWORD_DEFAULT),$id]);flash('success','User action completed.');redirect('admin/users.php');}$q=trim((string)($_GET['q']??''));$s=db()->prepare('SELECT user_id,name,email,academic_year,status,last_login_at,created_at FROM users WHERE role="student" AND (name LIKE ? OR email LIKE ?) ORDER BY created_at DESC');$s->execute(["%$q%","%$q%"]);$rows=$s->fetchAll();$pageTitle='Users';$activePage='users';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">USER MANAGEMENT</span><h1>Student accounts</h1><p>View, enable/disable and reset accounts.</p></div></section><section class="panel"><form class="filter-bar"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search name or email"><button class="btn btn-primary">Search</button></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Year</th><th>Status</th><th>Last login</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as$u):?><tr><td><strong><?=e($u['name'])?></strong><small class="table-sub"><?=e($u['email'])?></small></td><td><?=e($u['academic_year']?:'—')?></td><td><span class="status <?=$u['status']==='active'?'income':'expense'?>"><?=e($u['status'])?></span></td><td><?=$u['last_login_at']?e(date('d M Y H:i',strtotime($u['last_login_at']))):'Never'?></td><td><div class="action-stack"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><input type="hidden" name="action" value="toggle"><button class="text-button"><?=$u['status']==='active'?'Disable':'Enable'?></button></form><form method="post" style="display:flex;gap:5px"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="user_id" value="<?=$u['user_id']?>"><input type="hidden" name="action" value="reset"><input class="input" style="min-height:30px;width:115px;font-size:8px" name="new_password" placeholder="New password" required><button class="text-button">Reset</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>